def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''

    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window_counts = {}
    start = 0
    min_window_length = float('inf')
    min_window_start = 0

    for end in range(len(s)):
        char = s[end]
        if char in dict_t:
            if char not in window_counts:
                window_counts[char] = 0
            window_counts[char] += 1
            if window_counts[char] == dict_t[char]:
                formed += 1

        while formed == required and start <= end:
            char = s[start]
            if char in dict_t and window_counts[char] == dict_t[char]:
                formed -= 1
            window_counts[char] -= 1
            if char in dict_t and window_counts[char] < dict_t[char]:
                required -= 1
            if min_window_length > end - start + 1:
                min_window_length = end - start + 1
                min_window_start = start

            start += 1

    return "" if min_window_length == float('inf') else s[min_window_start : min_window_start + min_window_length]
```
