def regex_match(s: str, p: str) -> bool:
    s_len = len(s)
    p_len = len(p)
    if p_len == 0:
        return False
    if p_len == 1:
        if p == '.':
            return True
        else:
            return False
    if p[0] == '*':
        if p[1] == '.' or p[1] == s[0]:
            return regex_match(s[1:], p[2:]) or regex_match(s, p[2:])
    if p[p_len - 1] == '*':
        if p[p_len - 2] == '.' or p[p_len - 2] == s[s_len - 1]:
            return regex_match(s[:s_len - 1], p[0:p_len - 2]) or regex_match(s, p[0:p_len - 2])
    if p[0] == '.' or p[0] == s[0]:
        return regex_match(s[1:], p[1:])
    return False
```
