def balanced_brackets(s: str) -> bool:
    stack = []
    bracket_pairs = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in bracket_pairs.values():  # Opening bracket
            stack.append(char)
        elif char in bracket_pairs.keys():  # Closing bracket
            if not stack or stack.pop() != bracket_pairs[char]:
                return False
    return not stack
```

