def evaluate(expr: str) -> int:
    precedence = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
    }
    operators = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: int(a / b),
    }

    if not expr:
        return 0

    expr = expr.replace(" ", "")

    res = 0
    num = 0
    stack = []

    for i in range(len(expr)):
        if expr[i].isdigit():
            num = num * 10 + int(expr[i])
        elif expr[i] in operators:
            if stack:
                res = operators[expr[i]](res, num)
                num = 0
            stack.append(res)
            stack.append(expr[i])
            res = 0
        elif expr[i] == "(":
            stack.append(expr[i])
        elif expr[i] == ")":
            while stack[-1] != "(":
                res = operators[stack.pop()](res, num)
                num = 0
            stack.pop()

    res = operators[expr[-1]](res, num)
    return res
```

