def word_break(s: str, words: list[str]) -> bool:
    dp = [False] * (len(s) + 1)
    dp[0] = True
    for i in range(1, len(s) + 1):
        for word in words:
            if s[i - len(word)] == word[0] and dp[i - len(word)] and dp[i - 1]:
                dp[i] = True
                break
