def next_permutation(nums: list[int]) -> list[int]:
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i >= 0:
        nums[i], nums[len(nums) - 1] = nums[len(nums) - 1], nums[i]
    else:
        return nums
    j = len(nums) - 1
    while j > 0 and nums[j] <= nums[j - 1]:
        j -= 1
    nums[j], nums[len(nums) - 1] = nums[len(nums) - 1], nums[j]
    return nums
```
