def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Duration string cannot be empty.")
    parts = s.split()
    total_seconds = 0
    for part in parts:
        if part.isdigit():
            total_seconds += int(part) * 60**((parts.index(part) + 1) % 4)
        elif part in ('d', 'h', 'm', 's'):
            total_seconds += int(part) * 60**((parts.index(part) + 1) % 4)
        else:
            raise ValueError(f"Invalid unit: {part}")
    return total_seconds
```
