def n_queens(n: int) -> int:
    """
    Return the number of ways to place n non-attacking queens on an n x n chessboard.
    """
    if n == 1:
        return 1
    dp = [[0 for _ in range(n)] for _ in range(n)]

    def solve(row: int):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(row, col, dp):
                dp[row][col] = 1
                count += solve(row + 1)
                dp[row][col] = 0
        return count

    return solve(0)

def is_safe(row: int, col: int, dp: list) -> bool:
    for i in range(row):
        for j in range(col):
            if dp[i][j] == 1:
                return False
    return True
```

