def decode_ways(s: str) -> int:
    if s.startswith('0'):
        return 0
    if len(s) == 0:
        return 0
    dp = [0] * 27
    dp[0] = 1
    for i in range(1, len(s)):
        if s[i] >= 'A':
            dp[ord(s[i]) - ord('A') + 1] = dp[ord(s[i]) - ord('A') + 1] + dp[ord(s[i - 1]) - ord('A') + 1]
        else:
            dp[ord(s[i]) - ord('0') + 1] = dp[ord(s[i]) - ord('0') + 1] + dp[ord(s[i - 1]) - ord('0') + 1]
    return dp[ord(s[-1]) - ord('0') + 1]
```
