def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''
    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0 
    window_counts = {}

    l, r = 0, 0
    ans = float('inf'), None, None  

    while r < len(s):
        char = s[r]
        if char in window_counts:
            formed += 1
            window_counts[char] += 1
        else:
            window_counts[char] = 1

        if char in dict_t and window_counts[char] == dict_t[char]:
            required -= 1

        while l <= r and formed == required:
            char = s[l]
            if ans[0] > r - l + 1:
                ans = (r - l + 1, l, r)

            window_counts[char] -= 1
            if char in dict_t and window_counts[char] < dict_t[char]:
                formed -= 1

            l += 1

        r += 1

    if ans[0] == float('inf'):
        return ''
    else:
        return s[ans[1]:ans[2] + 1] 

