def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    in_degree = [0] * n
    for u, v in edges:
        in_degree[u] += 1
    queue = [i for i in range(n) if in_degree[i] == 0]
    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in range(n):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if len(result) != n:
        return []  # Cycle detected
    return result
