def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''

    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window_counts = {}

    l, r = 0, 0
    min_window_length = float('inf')
    min_window_start = 0

    while r < len(s):
        c = s[r]
        if c in dict_t:
            if c not in window_counts:
                window_counts[c] = 0
            window_counts[c] += 1
            if window_counts[c] == dict_t[c]:
                formed += 1

        while formed == required:
            if r - l + 1 < min_window_length:
                min_window_length = r - l + 1
                min_window_start = l
            c = s[l]
            if c in dict_t:
                if window_counts[c] == dict_t[c]:
                    formed -= 1
                window_counts[c] -= 1
            l += 1
        r += 1

    if min_window_length == float('inf'):
        return ''
    else:
        return s[min_window_start:min_window_start + min_window_length]

