    dp = [1] * n

    # Iterate through the array.
    for i in range(1, n):
        # For each index, check the previous indices.
        for j in range(i):
            # If the current element is greater than the previous element and the length of the LIS ending at the previous index plus 1 is greater than the length of the LIS ending at the current index, update the length of the LIS ending at the current index.
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1

