def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''

    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window_counts = {}
    start = 0
    min_window_length = float('inf')
    min_window_start = 0

    for end in range(len(s)):
        right_char = s[end]
        if right_char in dict_t:
            if right_char not in window_counts:
                window_counts[right_char] = 0
            window_counts[right_char] += 1
            if window_counts[right_char] == dict_t[right_char]:
                formed += 1

        while formed == required and start < end:
            left_char = s[start]
            if left_char in dict_t and window_counts[left_char] == dict_t[left_char]:
                formed -= 1

            if end - start + 1 < min_window_length:
                min_window_length = end - start + 1
                min_window_start = start

            start += 1

    if min_window_length == float('inf'):
        return ''
    else:
        return s[min_window_start : min_window_start + min_window_length]

