        grid[row][col] = '0'  # Mark the cell as visited
        # Explore adjacent cells in 4 directions
        dfs(row + 1, col)
        dfs(row - 1, col)
        dfs(row, col + 1)
        dfs(row, col - 1)

    for i in range(rows):
        for j in range(cols):
