def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    dist = [-1] * (n + 1)  # Initialize distances to -1 for unreachable nodes
    dist[src] = 0  # Set distance from src to itself to 0
    for _ in range(n + 1):
        for u, v, w in edges:
            if dist[u] != -1 and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w  # Relax the distance if a shorter path is found
    return dist[1:]  # Return distances starting from 1
