def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Duration string cannot be empty.")
    parts = s.split(' ')
    total_seconds = 0
    for part in parts:
        if part.lower() in ('d', 'h', 'm', 's'):
            try:
                amount = int(part.strip('dhmns'))
                if part.lower() == 'd':
                    total_seconds += amount * 86400
                elif part.lower() == 'h':
                    total_seconds += amount * 3600
                elif part.lower() == 'm':
                    total_seconds += amount * 60
                elif part.lower() == 's':
                    total_seconds += amount * 1
            except ValueError:
                raise ValueError(f"Invalid duration unit: {part}")
    return total_seconds
