def n_queens(n: int) -> int:
    """
    Return the number of ways to place n non-attacking queens on an n x n chessboard.
    """
    if n <= 0:
        return 0

    n_queens = [0 for i in range(n)]

    def backtrack(row):
        if row == n:
            return 1

        for col in range(n):
            if is_safe(row, col):
                n_queens[row] += backtrack(row + 1)

    def is_safe(row, col):
        for i in range(row):
            if (i==row) and (n_queens[i] == 0):
                return False
            if (abs(i-row)) <= 1:
                return True

        return False

    return backtrack(0)

