def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''

    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window = {}
    left, right = 0, 0
    ans = float('inf'), None, None

    while right < len(s):
        char = s[right]
        if char in window:
            formed += 1
        if char not in dict_t:
            continue
        if char in window and dict_t[char] == window[char]:
            formed += 1
        window[char] = window.get(char, 0) + 1

        while left <= right and formed == required:
            char = s[left]
            if right - left + 1 < ans[0]:
                ans = (right - left + 1, left, right)
            if char in window and dict_t[char] == window[char]:
                formed -= 1
            window[char] -= 1
            left += 1
        right += 1

    if ans[0] == float('inf'):
        return ''
    else:
        return s[ans[1] : ans[2] + 1]

