def regex_match(s: str, p: str) -> bool:
    s_len = len(s)
    p_len = len(p)

    if p_len == 0:
        return False

    if s_len < p_len:
        return False

    for i in range(s_len):
        if p[i] == '*':
            if p[i-1] in s[i-1:i+1] or p[i-1] == '.':
                if i > 0:
                    p_len -= 1
                    if i < s_len:
                        return regex_match(s[i:s_len], p[i+1:])
                else:
                    return True
            else:
                return False
        elif p[i] == '.' or p[i] == s[i]:
            if i < s_len-1:
                p_len -= 1
                if p_len == 0:
                    return True
                return regex_match(s[i+1:], p[i+1:])
        else:
            return False 
    return False
