def n_queens(n: int) -> int:
    """
    Calculates the number of ways to place n non-attacking queens on an n x n chessboard.
    """
    dp = [[False for _ in range(n)] for _ in range(n)]

    def solve(row):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(row, col, dp):
                dp[row][col] = True
                count += solve(row + 1)
                dp[row][col] = False
        return count

    return solve(0)

def is_safe(row, col, dp):
    for i in range(row):
        if dp[i][col]:
            return False
    for i in range(col):
        if dp[row][i]:
            return False
    for i in range(row, n):
        for j in range(col, n):
            if dp[i][j]:
                return False
    return True

