def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ""

    dict_t = {}
    for c in t:
        if c not in dict_t:
            dict_t[c] = 0
        dict_t[c] += 1

    required = len(dict_t)
    formed = 0
    window_counts = {}
    start, end = 0, 0
    min_window_length = float('inf')
    min_window_start = 0

    while end < len(s):
        character = s[end]
        if character in dict_t:
            if character not in window_counts:
                window_counts[character] = 0
            window_counts[character] += 1
            if window_counts[character] == dict_t[character]:
                formed += 1

        while formed == required:
            if end - start + 1 < min_window_length:
                min_window_length = end - start + 1
                min_window_start = start
            character = s[start]
            if character in dict_t:
                window_counts[character] -= 1
                if window_counts[character] < dict_t[character]:
                    formed -= 1
            start += 1
        end += 1
    if min_window_length == float('inf'):
        return ""
    return s[min_window_start : min_window_start + min_window_length]

